// Walk-frames measurement build (Russell, 28 Oct). NOT the wallet: it is
// built only with `flutter build apk --target integration_test/
// walk_frames_main.dart`, and the release build's lib/main.dart does not
// import it (test/walk_frames_guard_test.dart checks that).
//
// The wallet shell is on screen while the production walk below a
// checkpoint (ShearLedger _proveBelowPin, native ShearHash-v3) runs in a
// worker isolate over a real mined, linking regtest header chain that
// walk_chain_data.dart carries (generated by tool/gen_walk_chain_dart.mjs).
// Frame build and raster times come from SchedulerBinding.addTimingsCallback.
// One logcat line, tag SHEAR_WALK_FRAMES, carries the result as JSON.
import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'dart:isolate';
import 'dart:typed_data';
import 'dart:ui' show FrameTiming;

import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:flutter/scheduler.dart';
import 'package:shear_wallet/main.dart';
import 'package:shear_wallet/shear_ledger.dart';
import 'package:shear_wallet/shear_session.dart';

import 'walk_chain_data.dart';

/// Top level, so the isolate closure carries only [input].
Future<Map<String, dynamic>> _walkInWorker(Map<String, dynamic> input) =>
    Isolate.run(() => walkBelowCheckpointWorker(input));

double _pct(List<int> us, double p) {
  if (us.isEmpty) return 0;
  final s = List<int>.from(us)..sort();
  final i = ((s.length - 1) * p).round();
  return s[i] / 1000.0;
}

double _max(List<int> us) => us.isEmpty ? 0 : us.reduce((a, b) => a > b ? a : b) / 1000.0;

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  final headers = base64Decode(kWalkChainChunks.join());
  final total = headers.length ~/ 128;
  final dir = await Directory.systemTemp.createTemp('shear-walk-frames-');
  final session = ShearSession(store: File('${dir.path}/session.json'));
  await session.loadOrCreate();
  await session.setPassword('walk-frames-build-not-a-wallet');
  final ledger = ShearLedger();
  final status = ValueNotifier<String>('Verifying checkpoint headers 0/$total');

  runApp(Directionality(
    textDirection: TextDirection.ltr,
    child: Stack(children: [
      ShearWalletApp(session: session, ledger: ledger, startUnlocked: true, skipPoolSync: true),
      Positioned(
        left: 0,
        right: 0,
        bottom: 0,
        child: Material(
          color: const Color(0xEE222222),
          child: Padding(
            padding: const EdgeInsets.all(12),
            child: Row(children: [
              const SizedBox(width: 20, height: 20, child: CircularProgressIndicator(strokeWidth: 2)),
              const SizedBox(width: 12),
              Expanded(
                child: ValueListenableBuilder<String>(
                  valueListenable: status,
                  builder: (_, s, __) => Text(s, style: const TextStyle(color: Colors.white)),
                ),
              ),
            ]),
          ),
        ),
      ),
    ]),
  ));

  // Let the shell settle before measuring.
  await Future<void>.delayed(const Duration(seconds: 3));
  final build = <int>[];
  final raster = <int>[];
  final span = <int>[];
  var measuring = true;
  SchedulerBinding.instance.addTimingsCallback((List<FrameTiming> list) {
    if (!measuring) return;
    for (final t in list) {
      build.add(t.buildDuration.inMicroseconds);
      raster.add(t.rasterDuration.inMicroseconds);
      span.add(t.totalSpan.inMicroseconds);
    }
  });

  final progress = ReceivePort();
  var lastTenth = -1;
  progress.listen((m) {
    if (m is Map && m['event'] == 'walk') {
      final d = m['done'];
      final t = m['total'];
      if (t is int && t > 0 && d is int) {
        status.value = 'Verifying checkpoint headers $d/$t';
        final tenth = d * 10 ~/ t;
        if (tenth != lastTenth) {
          lastTenth = tenth;
          // ignore: avoid_print
          print('SHEAR_WALK_PROGRESS $d/$t');
        }
      }
    }
  });
  // ignore: avoid_print
  print('SHEAR_WALK_START headers=$total');
  final port = progress.sendPort;
  final input = <String, dynamic>{
    'headers': Uint8List.fromList(headers),
    'pin': kWalkPin,
    'progress': port,
  };
  final sw = Stopwatch()..start();
  final result = await _walkInWorker(input);
  final wallMs = sw.elapsedMilliseconds;
  // Two more seconds of frames after the walk, then stop.
  await Future<void>.delayed(const Duration(seconds: 2));
  measuring = false;
  progress.close();
  status.value = result['ok'] == true ? 'Walk done: linked' : 'Walk refused';

  final over16 = [for (var i = 0; i < span.length; i++) if (build[i] > 16000 || raster[i] > 16000) i].length;
  final n = (result['headers'] as num?)?.toInt() ?? total;
  final out = {
    'mode': kReleaseMode ? 'release' : (kProfileMode ? 'profile' : 'debug'),
    'ok': result['ok'],
    'backend': result['backend'],
    'headers': n,
    'walk_ms': result['ms'],
    'wall_ms': wallMs,
    'per_header_ms': n > 0 ? ((result['ms'] as num) / n).toStringAsFixed(1) : null,
    'frames': span.length,
    'frames_over_16ms': over16,
    'build_worst_ms': _max(build),
    'build_p99_ms': _pct(build, 0.99),
    'raster_worst_ms': _max(raster),
    'raster_p99_ms': _pct(raster, 0.99),
    'span_worst_ms': _max(span),
    'span_p99_ms': _pct(span, 0.99),
  };
  // ignore: avoid_print
  print('SHEAR_WALK_FRAMES ${jsonEncode(out)}');
}
